const tabID = "tab_1f16031a-98f4-465d-acef-2ca2fe83891e";
const script = `
(function(){
  const metrics = [];
  for (let i=1;i<=9;i++) metrics.push({id:i,status:'pass',score_earned:RUBRIC[i].pts,observation:'Agent did this correctly.',recommendation:''});
  metrics.push({id:10,status:'pass',score_earned:5,observation:'Clear delivery.',recommendation:''});
  metrics.push({id:11,status:'partial',score_earned:3,observation:'Mild acknowledgement only.',recommendation:'Acknowledge emotion explicitly.'});
  metrics.push({id:12,status:'pass',score_earned:5,observation:'Listened well.',recommendation:''});
  metrics.push({id:13,status:'pass',score_earned:5,observation:'Friendly tone.',recommendation:''});
  metrics.push({id:14,status:'fail',score_earned:0,observation:'Rambled before resolving.',recommendation:'State the resolution first.'});
  metrics.push({id:15,status:'pass',score_earned:5,observation:'Confident.',recommendation:''});
  for (let i=16;i<=18;i++) metrics.push({id:i,status:'not-observed',score_earned:0,observation:'Not observed.',recommendation:''});
  const raw = {
    reason_for_call:'Service appointment reschedule',
    metrics,
    strengths:['Warm greeting','Accurate data entry'],
    opportunities:['Be more concise','Acknowledge emotion'],
    concerns:[],
    recommended_actions:['Review hold procedure','Shadow a top performer'],
    coaching_suggestions:[{area:'Efficiency',suggestion:'Lead with the resolution.',example:'Your appointment is moved to Thursday at 10 AM.'}],
    coaching_notes:'Solid call overall with one efficiency gap.'
  };
  analysisResults = normalizeResult(raw);
  currentTranscript = 'Agent: Thanks for calling Downtown Ford, this is Maria.\\nCustomer: Hi, I need to move my service appointment.';
  document.getElementById('agentName').value='Maria Santos';
  document.getElementById('callDate').value='2026-09-24';
  document.getElementById('customerName').value='John Reyes';
  document.getElementById('dealership').value='Downtown Ford';
  renderResults();
  return JSON.stringify({grade: analysisResults.grade, total: analysisResults.total, passed: analysisResults.passed, autoFail: analysisResults.autoFail, sec: analysisResults.sections.map(s=>s.earned), rows: analysisResults.rows.length});
})()`;
const r = await tools.browser.evaluate({tabID, script});
return r.value;

