(function(){
  // reset to step 1 clean state first
  document.getElementById('resultsSection').style.display='none';
  document.getElementById('uploadSection').style.display='block';

  // 1. key modal opens
  document.getElementById('keyBtn').click();
  const modalOpen = document.getElementById('keyModal').classList.contains('show');
  document.getElementById('keyCancel').click();

  // 2. save a fake key
  document.getElementById('keyBtn').click();
  document.getElementById('keyInput').value = 'gsk_test123456789';
  document.getElementById('keySave').click();
  const keyLabel = document.getElementById('keyBtn').textContent;
  const status = document.getElementById('keyStatus').textContent;

  // 3. analyze with no audio + no transcript -> validation error
  document.getElementById('infoSection').style.display='block';
  document.getElementById('agentName').value='Maria';
  document.getElementById('callDate').value='2026-09-24';
  analyzeCall();

  const err = document.getElementById('errorMessage').textContent;
  const errShown = document.getElementById('errorMessage').classList.contains('show');
  return JSON.stringify({modalOpen, keyLabel, status, errShown, err});
})()`});
return r.value;

