/* Ask Groq which models this key can actually use, so we never guess. */
async function discoverModels(apiKey) {
    try {
        const res = await fetch(MODELS_URL, { headers: { 'Authorization': 'Bearer ' + apiKey } });
        if (!res.ok) return null;
        const data = await res.json();
        const ids = (Array.isArray(data.data) ? data.data : [])
            .map((m) => m && m.id)
            .filter((id) => typeof id === 'string' && !CHAT_MODEL_EXCLUDE_RE.test(id));
        if (!ids.length) return null;
        const ordered = CHAT_MODELS.filter((m) => ids.includes(m));
        ids.forEach((id) => { if (!ordered.includes(id) && CHAT_MODEL_RE.test(id)) ordered.push(id); });
        return ordered.length ? ordered : ids;
    } catch (e) {
        return null; // discovery is best-effort — fall back to CHAT_MODELS
    }
}

async function groqScore(transcript, agentName, callDate, apiKey) {
    const messages = [
        {
            role: 'system',
            content: 'You are a meticulous QA scoring engine. You output valid JSON only, never markdown or prose.'
        },
        { role: 'user', content: buildScoringPrompt(transcript, agentName, callDate) }
    ];

    const discovered = await discoverModels(apiKey);
    const candidates = (discovered || CHAT_MODELS).slice(0, 5);

    let lastErr = null;

    for (const model of candidates) {
        // Try with JSON mode first; if this model rejects response_format, retry plain.
        const payloadVariants = [
            { response_format: { type: 'json_object' } },
            {}
        ];

        for (let v = 0; v < payloadVariants.length; v++) {
            let res;
            try {
                res = await fetch(CHAT_URL, {
                    method: 'POST',
                    headers: {
                        'Authorization': 'Bearer ' + apiKey,
                        'Content-Type': 'application/json'
                    },
                    body: JSON.stringify(Object.assign({
                        model: model,
                        messages: messages,
                        temperature: 0.2,
                        max_tokens: 8000
                    }, payloadVariants[v]))
                });
            } catch (e) {
                throw new Error('Network error reaching the scoring service — check your connection.');
            }

            let data = null;
            try { data = await res.json(); } catch (e) { /* non-JSON */ }
            const errMsg = data && data.error && data.error.message ? data.error.message : ('HTTP ' + res.status);

            if (res.ok && data && data.choices && data.choices[0] && data.choices[0].message) {
                const raw = data.choices[0].message.content || '';
                const parsed = tryParseJSON(raw);
                if (parsed) return parsed;
                lastErr = new Error('The scoring model "' + model + '" returned malformed JSON — please run the analysis again.');
                break; // malformed output: move on to the next model
            }

            if (res.status === 401 || res.status === 403) {
                throw new Error('Scoring rejected the API key (' + errMsg + '). Open ⚙ API Key and paste a valid key from console.groq.com/keys.');
            }

            // This model refused the request — decide whether to retry without JSON mode or skip it.
            const modelUnavailable = /does not exist|do not have access|model_not_found|decommissioned|invalid model/i.test(errMsg);
            const fmtRejected = /response_format|json_object|structured|schema/i.test(errMsg);
            if (!modelUnavailable && fmtRejected && v === 0) continue;      // retry same model, plain output
            if (modelUnavailable || fmtRejected) { lastErr = new Error(errMsg); break; } // next model
            throw new Error('Scoring failed: ' + errMsg);
        }
    }

    throw lastErr || new Error('Scoring failed — no available model on this API key.');
}

