input.newString:
/* =====================================================================
   Export: shared mode that expands everything (open transcript, un-clipped
   scroll boxes, plain-text coaching notes) so nothing is cut off.
   ===================================================================== */
function applyExportMode(on) {
    const area = $('reportArea');
    if (on) {
        $('coachingNotesClone').textContent = $('coachingNotes').value;
        area.querySelectorAll('details').forEach((d) => {
            d.setAttribute('data-prev-open', d.open ? '1' : '0');
            d.open = true;
        });
        area.classList.add('export-mode');
    } else {
        area.classList.remove('export-mode');
        area.querySelectorAll('details[data-prev-open]').forEach((d) => {
            d.open = d.getAttribute('data-prev-open') === '1';
            d.removeAttribute('data-prev-open');
        });
    }
}

function exportTitle() {
    const agent = $('agentName').value.trim() || 'Agent';
    const date = $('callDate').value || '';
    return '<h2 style="font-family:\'IBM Plex Sans\',sans-serif;color:#1a2a4a;margin:0 0 14px;font-size:18px;">' +
        'CSR Call Evaluation — ' + esc(agent) + (date ? ' — ' + esc(date) : '') + '</h2>';
}

function buildExportHTML() {
    applyExportMode(true);
    try {
        const clone = $('reportArea').cloneNode(true); // keeps export-mode: un-clips boxes in the pasted doc
        const css = (document.querySelector('style') && document.querySelector('style').textContent) || '';
        return '<div>' + exportTitle() + '<style>' + css + '</style>' + clone.outerHTML + '</div>';
    } finally {
        applyExportMode(false);
    }
}

async function copyRichText(html, text) {
    // Preferred: rich HTML + plain text, keeps formatting in Word / Docs / Gmail.
    if (navigator.clipboard && typeof ClipboardItem !== 'undefined') {
        try {
            await navigator.clipboard.write([new ClipboardItem({
                'text/html': new Blob([html], { type: 'text/html' }),
                'text/plain': new Blob([text], { type: 'text/plain' })
            })]);
            return true;
        } catch (e) { /* blocked (permissions or non-secure context) — try the fallback */ }
    }
    // Fallback: selection + execCommand, copies rich text too.
    try {
        const holder = document.createElement('div');
        holder.contentEditable = 'true';
        holder.innerHTML = html;
        holder.style.cssText = 'position:fixed;left:-9999px;top:0;white-space:pre-wrap;';
        document.body.appendChild(holder);
        const range = document.createRange();
        range.selectNodeContents(holder);
        const sel = window.getSelection();
        sel.removeAllRanges();
        sel.addRange(range);
        let ok = false;
        try { ok = document.execCommand('copy'); } catch (e) { ok = false; }
        sel.removeAllRanges();
        holder.remove();
        return ok;
    } catch (e) { return false; }
}

/* =====================================================================
   Download PDF — one continuous document, nothing clipped or dropped
   ===================================================================== */
$('pdfBtn').addEventListener('click', async () => {
    if (!analysisResults) return;
    const el = $('reportArea');
    const btn = $('pdfBtn');
    const label = btn.textContent;

    if (typeof html2pdf === 'undefined') { window.print(); return; }

    btn.disabled = true;
    btn.textContent = 'Generating…';
    applyExportMode(true);

    // Large scale for short reports; back off for very tall ones so the
    // canvas never exceeds browser limits (which silently truncates pages).
    const scale = el.scrollHeight > 12000 ? 1 : (el.scrollHeight > 7000 ? 1.5 : 2);

    try {
        await html2pdf().set({
            margin: [8, 8, 12, 8],
            filename: 'call-evaluation-' + ($('agentName').value.trim().replace(/\s+/g, '-').toLowerCase() || 'report') + '.pdf',
            image: { type: 'jpeg', quality: 0.95 },
            html2canvas: { scale: scale, useCORS: true, backgroundColor: '#ffffff', scrollY: 0, windowWidth: el.scrollWidth },
            jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' },
            // 'css' + 'legacy' breaks between rows/sections instead of trying to
            // fit whole sections on one page (which dropped content before).
            pagebreak: { mode: ['css', 'legacy'], before: '.qa-section', after: '.coach-card' }
        }).from(el).save();
    } catch (e) {
        window.print(); // last-resort: browser print-to-PDF
    } finally {
        applyExportMode(false);
        btn.disabled = false;
        btn.textContent = label;
    }
});

/* =====================================================================
   Copy the full Step 3 — Evaluation & Coaching output
   ===================================================================== */
$('copyBtn').addEventListener('click', async () => {
    if (!analysisResults) return;
    const btn = $('copyBtn');
    const label = btn.textContent;

    const html = buildExportHTML();

    applyExportMode(true);
    const title = 'CSR Call Evaluation — ' + ($('agentName').value.trim() || 'Agent') +
        ($('callDate').value ? ' — ' + $('callDate').value : '') + '\n\n';
    const text = title + $('reportArea').innerText.trim();
    applyExportMode(false);

    btn.disabled = true;
    btn.textContent = 'Copying…';
    const ok = await copyRichText(html, text);
    btn.disabled = false;
    btn.textContent = label;

    if (ok) showSuccess('✓ Evaluation & Coaching copied — paste it into Word, Gmail, or Google Docs.');
    else showError('Copy was blocked by the browser. Select the report text manually (Ctrl+C) or use Download Report (PDF).');
});

/* Print fallback (Ctrl+P / print dialog): expand collapsed panels first. */
window.addEventListener('beforeprint', () => applyExportMode(true));
window.addEventListener('afterprint', () => applyExportMode(false));

