  metrics.push({id:10,status:'pass',score_earned:5,observation:'Clear delivery throughout.',recommendation:''});
  metrics.push({id:11,status:'partial',score_earned:3,observation:'Mild acknowledgement only.',recommendation:'Acknowledge emotion explicitly.'});
  metrics.push({id:12,status:'pass',score_earned:5,observation:'Listened well.',recommendation:''});
  metrics.push({id:13,status:'pass',score_earned:5,observation:'Friendly tone.',recommendation:''});
  metrics.push({id:14,status:'fail',score_earned:0,observation:'Rambled before resolving.',recommendation:'State the resolution first.'});
  metrics.push({id:15,status:'pass',score_earned:5,observation:'Confident.',recommendation:''});
  for (let i=16;i<=18;i++) metrics.push({id:i,status:'not-observed',score_earned:0,observation:'Not observed in this call.',recommendation:''});
  analysisResults = normalizeResult({
    reason_for_call:'Service appointment reschedule',
    metrics,
    strengths:['Warm greeting and accurate data entry','Verified customer information before proceeding','Professional closing with next steps confirmed'],
    opportunities:['Be more concise when stating the resolution','Acknowledge customer emotion earlier in the call'],
    concerns:['Hold duration exceeded the 3-ring standard twice during this call.'],
    recommended_actions:['Review the hold procedure standard this week','Shadow a top performer for two calls','Re-run the QA form checklist before dispositioning'],
    coaching_suggestions:[
      {area:'Efficiency',suggestion:'Lead with the resolution, then give detail.',example:'Your appointment is moved to Thursday at 10 AM — let me confirm the details.'},
      {area:'Empathy',suggestion:'Name the emotion before solving.',example:'I understand this is frustrating, and I will get it sorted for you.'}
    ],
