const tabID = "tab_205f5c91-42cd-4ae0-af25-b4e69428deb9";
const r = await tools.browser.evaluate({tabID, script: `
(async function(){
  applyExportMode(true);
  const el = document.getElementById('reportArea');
  const worker = html2pdf().set({html2canvas:{scale:1, backgroundColor:'#ffffff', scrollY:0}}).from(el).toContainer().toCanvas();
  await worker;
  const canvas = worker.get('canvas');
  const out = {canvasH: canvas.height, canvasW: canvas.width, elH: el.scrollHeight, ratio: canvas.height/el.scrollHeight};
  // render the bottom slice (end of transcript + AI note) large enough to read
  document.body.innerHTML = '';
  document.body.style.background = '#fff';
  const sliceH = Math.min(1400, canvas.height);
  const c2 = document.createElement('canvas');
  c2.width = Math.min(canvas.width, 900);
  c2.height = Math.round(sliceH * (c2.width / canvas.width));
  const ctx = c2.getContext('2d');
  ctx.fillStyle = '#fff'; ctx.fillRect(0,0,c2.width,c2.height);
  ctx.drawImage(canvas, 0, canvas.height - sliceH, canvas.width, sliceH, 0, 0, c2.width, c2.height);
  const img = new Image();
  img.src = c2.toDataURL('image/png');
  img.style.cssText = 'width:900px;display:block;';
  document.body.appendChild(img);
  return JSON.stringify(out);
})()`});
return r.value;

