function normalizeResult(raw) {
    const rawMetrics = Array.isArray(raw.metrics) ? raw.metrics : [];
    const byId = {};
    rawMetrics.forEach((m, i) => {
        const id = m && m.id != null ? Number(m.id) : i + 1;
        if (RUBRIC[id] && byId[id] === undefined) byId[id] = m;
    });

    const rows = [];
    const secEarned = {};
    const secPossible = {};
    SECTIONS.forEach((s) => { secEarned[s.id] = 0; secPossible[s.id] = 0; });
    const autoFailItems = [];

    /* #13 Transfer Handling (and any other conditional item) only scores when the
       call disposition contains the word "Transfer". Otherwise it is N/A: excluded
       from the denominator instead of counting as a fail — same as the audit sheet's
       "N/A" column. The N/A column on the PDF also lets the scorer mark any item
       genuinely not applicable; those points are simply not available on that call. */
    const disposition = ($('disposition') ? $('disposition').value : '').trim();
    const transferActive = /transfer/i.test(disposition);

    for (let id = FIRST_ID; id <= LAST_ID; id++) {
        const rubric = RUBRIC[id];
        const m = byId[id] || {};
        const statusRaw = String(m.status || '').toLowerCase().trim();
        const conditionalOff = rubric.conditional === 'transfer' && !transferActive;
        let status, earned;
        let deactivated = conditionalOff;

        if (conditionalOff) {
            // Disposition has no "Transfer" → deactivated (N/A).
            status = 'na';
            earned = 0;
        } else if (rubric.zero) {
            // Zero tolerance: auto fail / PIP enrollment — TRUE/FALSE style.
            const fail = ['auto-fail', 'auto_fail', 'autofail', 'fail', 'triggered', 'yes', 'true'].includes(statusRaw);
            status = fail ? 'auto-fail' : 'not-observed';
            earned = 0;
            if (fail) autoFailItems.push(id);
        } else if (['na', 'n/a', 'not applicable'].includes(statusRaw)) {
            status = 'na';
            earned = 0;
            deactivated = true;
        } else {
            // Point-based scoring (the sheet allows partial credit, e.g. 2 of 4).
            const rawPts = m.score_earned;
            const n = Number(rawPts);
            if (rawPts != null && String(rawPts).trim() !== '' && isFinite(n)) {
                earned = Math.min(rubric.pts, Math.max(0, Math.round(n)));
            } else if (['pass', 'yes', 'full', 'full points'].includes(statusRaw)) {
                earned = rubric.pts;
            } else if (['partial', 'partially', 'part'].includes(statusRaw)) {
                earned = Math.round(rubric.pts / 2);
            } else {
                earned = 0; // fail / no / missing evidence
            }
            status = earned >= rubric.pts ? 'pass' : earned > 0 ? 'partial' : 'fail';
        }

        let observation = typeof m.observation === 'string' ? m.observation.trim() : '';
        let recommendation = typeof m.recommendation === 'string' ? m.recommendation.trim() : '';
        if (conditionalOff && !observation) {
            observation = 'N/A — disposition "' + (disposition || '(not set)') + '" has no "Transfer" keyword, so this item is not scored.';
            recommendation = '';
        }

        rows.push({
            id,
            sec: rubric.sec,
            title: rubric.title,
            criteria: rubric.criteria,
            possible: rubric.pts,
            zero: !!rubric.zero,
            deactivated,
            status,
            earned,
            observation,
            recommendation
        });

        secEarned[rubric.sec] = (secEarned[rubric.sec] || 0) + earned;
        if (!deactivated && !rubric.zero) {
            secPossible[rubric.sec] = (secPossible[rubric.sec] || 0) + rubric.pts;
        }
    }

    const scoreable = rows.filter((r) => !r.zero && !r.deactivated);

