    /* Sectioned rubric, grouped exactly like the DealerFocus evaluation sheet. */
    const rubricTable = SECTIONS.map((s) => {
        const ids = idsOf(s.id);
        const secPts = ids.reduce((t, id) => t + RUBRIC[id].pts, 0);
        const items = ids.map((id) => {
            const r = RUBRIC[id];
            return '  - id ' + id + ': "' + r.title + '" — ' + r.criteria +
                (r.zero ? '  [ZERO-TOLERANCE: auto fail / PIP enrollment]'
                        : '  [' + r.pts + ' pts possible]');
        }).join('\n');
        return s.name + (s.zero ? '' : ' (' + secPts + ' pts)') + '\n' + items;
    }).join('\n');

    const jsonLines = Object.keys(RUBRIC).map(Number).map((id) => {
        const r = RUBRIC[id];
        const st = r.zero ? 'auto-fail|not-observed' : 'pass|partial|fail|na';
        return '    {"id": ' + id + ', "status": "' + st + '", "score_earned": ' + (r.zero ? 0 : r.pts) +
            ', "observation": "...", "recommendation": ""}';
    }).join(',\n');

    return 'You are a strict automotive dealership QA auditor scoring a customer service call transcript against the DealerFocus evaluation sheet.\n\n' +
        'Agent: ' + agentName + '\nCall date: ' + callDate + '\nCall disposition: "' + (disposition || '(not set)') + '"\n\n' +
        'TRANSCRIPT:\n"""\n' + transcript.slice(0, 60000) + '\n"""\n\n' +
        'SCORE EVERY ONE OF THE ' + LAST_ID + ' ITEMS BELOW AGAINST THE TRANSCRIPT:\n' + rubricTable + '\n\n' +
        'SCORING RULES:\n' +
        '1. Scored items (ids 1-23) are worth 0 up to their maximum points. Award FULL points only when the behavior is clearly ' +
        'evidenced in the transcript, PARTIAL credit when it is partly demonstrated (e.g. 2 of 4, or set status "partial"), and 0 when ' +
        'it did not happen or there is no evidence. status must be "pass" (full points), "partial" (some points), or "fail" (0 points), ' +
        'and score_earned must be the actual points awarded.\n' +
        '2. Zero-tolerance items (ids ' + ZERO_IDS_LABEL + ') are TRUE/FALSE: status must be exactly "auto-fail" if observed, otherwise ' +
        '"not-observed", always with score_earned 0. If ANY of them is "auto-fail", the final grade becomes 0% and the call requires PIP enrollment review.\n' +
        '3. Use status "na" ONLY for an item that genuinely does not apply to this call; those points are removed from the available total ' +
        'instead of counting as a miss (this is the evaluation sheet\'s "N/A" column).\n' +
        '4. DISPOSITION RULE: item 13 (Transfer Handling) is only scored when the call disposition contains the word "Transfer". ' +
        (transferActive
            ? 'This disposition DOES contain "Transfer", so score item 13 normally.\n'
            : 'This disposition does NOT contain "Transfer", so set item 13 to status "na", score_earned 0.\n') +
        '5. Only award points that are clearly evidenced in the transcript. Be strict, not generous — never assume a behavior happened.\n' +
        '6. Every item needs a short "observation" quoting or paraphrasing what actually happened in the call, and a ' +
        '"recommendation" (empty string "" when fully passed).\n' +
        '7. The section totals add to 100 points; the final grade is points earned divided by points available (minus any N/A items), ' +
        'as a percentage. Passing threshold is 85%.\n' +
        '\n' +
        'RESPOND WITH STRICT JSON ONLY (no markdown, no commentary) IN EXACTLY THIS SHAPE:\n' +
        '{\n' +
