  const file = new File([blob], 'Ericka-CAN.mp3', { type: 'audio/mpeg' });
  const dt = new DataTransfer();
  dt.items.add(file);
  const input = document.getElementById('audioInput');
  input.files = dt.files;
  input.dispatchEvent(new Event('change', { bubbles: true }));
  const set = (id, val) => { const el = document.getElementById(id); el.value = val; el.dispatchEvent(new Event('input', {bubbles:true})); el.dispatchEvent(new Event('change', {bubbles:true})); };
  set('agentName', 'Ericka');
  set('callDate', '2026-09-27');
  set('dealership', 'Central Avenue Nissan');
  set('disposition', 'Successful Appointment');
  document.getElementById('analyzeBtn').click();
  const start = Date.now();
  while (Date.now() - start < 300000) {
    const shown = document.getElementById('resultsSection') && document.getElementById('resultsSection').style.display === 'block';
    if (shown) return { done: 'results', ms: Date.now() - start };
    const err = document.querySelector('.error, .error-msg, #errorMsg');
    if (err && err.offsetParent !== null && err.innerText.trim().length > 0) return { done: 'error', ms: Date.now() - start, errText: err.innerText };
