const tabID = "tab_205f5c91-42cd-4ae0-af25-b4e69428deb9";
await tools.browser.reload({tabID});
const v = await tools.browser.evaluate({tabID, script: `
(function(){
  const out = {};

  /* ---- A. ACCURACY RULE for items 4 / 7 / 8 ---- */
  const p = buildScoringPrompt('transcript', 'Agent', '2026-09-27', 'Successful Appointment');
  const rule6 = p.slice(p.indexOf('6. ACCURACY RULE'), p.indexOf('7. Every item'));
  out.accuracy = {
    rulePresent: rule6.length > 0,
    stepIsEnough: /doing the step is enough/.test(rule6),
    acceptsCallerGiven: /accept information given by the caller/.test(rule6),
    noReadback: /no read-back, confirmation or system lookup required/.test(rule6),
    coversAllThree: [4,7,8].every(n => rule6.indexOf('item'+n)>-1 || new RegExp('items?[^.]*\\\\b'+n+'\\\\b').test(rule6)),
    exceptionKept: /contradicts what the caller actually provided/.test(rule6),
    criteria: [4,7,8].map(id => ({
      id,
      hasStepRule: /doing the step is enough/.test(RUBRIC[id].criteria),
      mentionsCaller: /caller/.test(RUBRIC[id].criteria),
      text: RUBRIC[id].criteria
    })),
    stalePhrases: ['must be right','incomplete customer name','never full points','misspelled name']
      .filter(s => p.indexOf(s) > -1)
  };

  /* ---- B. CHECKLIST on Call Details tab ---- */
  const boxes = ['chkOpCode','chkAdvisor','chkData','chkHotAlert'].map(k => {
    const el = document.getElementById(k);
    const inStep2 = !!(el && el.closest('#infoSection'));
    return { key: k, exists: !!el, inCallDetailsTab: inStep2,
             checked: el.checked,
             label: el ? el.closest('label').textContent.replace(/\\s+/g,' ').trim() : null };
  });
  out.checklist = {
    boxes,
    mapsToItems: CHECKLIST.map(c => c.id).join(','),
    expectedItems: '10, 11, 12, 15',
    itemsMatch: CHECKLIST.map(c => c.id).join(',') === '10,11,12,15',
    inPrompt: p.indexOf('SYSTEM & SCHEDULER CHECKLIST') > -1,
    promptListsAll: [10,11,12,15].every(id => new RegExp('- id '+id+' ').test(p)),
    promptAuthoritative: /checklist is authoritative/.test(p),
    summaryStripField: $('summaryStrip').innerHTML.indexOf('System Checklist') === -1 ? 'rendered-with-results' : 'present'
  };

  /* ---- override behaviour (both directions) ---- */
  const mk = () => ({ metrics: Object.keys(RUBRIC).map(Number).map(id => {
      const r = RUBRIC[id];
      if (r.zero) return {id, status:'not-observed', score_earned:0, observation:'o', recommendation:''};
      return {id, status:'pass', score_earned:r.pts, observation:'model '+id, recommendation:''};
    }), strengths:[], opportunities:[], concerns:[], recommended_actions:[],
    coaching_suggestions:[], coaching_notes:'', reason_for_call:''});
  const g = (res,id) => { const r = res.rows.find(x=>x.id===id); return r.status+' '+r.earned+'/'+r.possible; };
  ['chkOpCode','chkAdvisor','chkData','chkHotAlert'].forEach(k => document.getElementById(k).checked = false);
  const allOff = normalizeResult(mk());
  ['chkOpCode','chkAdvisor','chkData','chkHotAlert'].forEach(k => document.getElementById(k).checked = true);
  const allOn = normalizeResult(mk());
  ['chkOpCode','chkAdvisor','chkData','chkHotAlert'].forEach(k => document.getElementById(k).checked = false);
  out.override = {
    uncheckedOverridesModelPass: [10,11,12,15].every(id => g(allOff,id).startsWith('fail 0/')),
    checkedOverridesToFull: [10,11,12,15].every(id => g(allOn,id).startsWith('pass')),
    uncheckedObs: allOff.rows.find(r=>r.id===10).observation,
    checkedObs: allOn.rows.find(r=>r.id===10).observation,
    uncheckedGrade: allOff.grade, checkedGrade: allOn.grade,
    checklistItemsAreTheOnlyOnesAffected: JSON.stringify(
      Object.keys(RUBRIC).map(Number).filter(id => g(allOff,id) !== g(allOn,id))) === '[10,11,12,15]'
  };
  return out;
})()`});
const con = await tools.browser.console({tabID, level: "error", limit: 20});
return {audit: v.value, errors: con.messages.map(m=>m.text)};

