    const coachBox = id => { const row = document.querySelector('[data-row="'+id+'"] .row-rec'); return row ? row.innerText.replace(/\\s+/g,' ').trim() : null; };
    return {
      grade: r.grade, total: r.total, possible: r.possibleActive, status: document.getElementById('gradeStatus').textContent,
      sections: r.sections.map(s => s.name + ' = ' + (s.zero ? 'zero-tolerance' : s.earned+'/'+s.possible)),
      skills: [17,18,19,20,21,22,23].map(brief),
