(async () => {
  try {
    document.getElementById('analyzeBtn').click();
    const start = Date.now();
    while (Date.now() - start < 300000) {
      const res = document.getElementById('resultsSection');
      if (res && res.style.display === 'block') return JSON.stringify({ done: 'results', ms: Date.now() - start });
      const errEl = document.querySelector('.error, .error-msg, #errorMsg, .alert-error');
      if (errEl && errEl.offsetParent !== null && errEl.innerText.trim().length > 0) return JSON.stringify({ done: 'error', ms: Date.now() - start, errText: errEl.innerText.slice(0,300) });
      await new Promise(r => setTimeout(r, 2000));
    }
    return JSON.stringify({ done: 'timeout' });
  } catch (e) { return 'THREW: ' + e; }
})()`});
return {r: r.value};

