const d = await tools.browser.evaluate({tabID, script: `
(function(){
  const names = ['transcript','currentTranscript','lastTranscript','gTranscript','window.transcriptText'];
  let t = null, found = null;
  for (const n of names) { try { const v = eval(n); if (typeof v === 'string' && v.length > 50) { t = v; found = n; break; } } catch(e){} }
  if (!t) { const ks = Object.keys(window).filter(k => /trans/i.test(k)); return JSON.stringify({globals: ks}); }
  const low = t.toLowerCase();
  const hits = ['email','e-mail','e mail','mail','@','text','aoa','confirm'].map(k => k + '=' + low.split(k).length);
  const snippets = [];
  ['email','@','aoa','text feature','send you'].forEach(k => {
    let i = 0;
    while ((i = low.indexOf(k, i)) > -1 && snippets.length < 12) { snippets.push(t.slice(Math.max(0,i-90), i+90).replace(/\\s+/g,' ')); i += k.length; }
  });
  return JSON.stringify({found, len: t.length, hits, snippets}, null, 1);
})()`});
return {out: d.value};

